def solve(gi):
    n=len(gi); m=len(gi[0])
    res=[row[:] for row in gi]
    def twins_rows(r, grid):
        out=[]
        for r2 in range(n):
            if r2==r: continue
            if all(grid[r][c]==6 or grid[r2][c]==grid[r][c] for c in range(m)): out.append(r2)
        return out
    changed=True
    while changed:
        changed=False
        for r in range(n):
            for c in range(m):
                if res[r][c]==6:
                    t=res[c][r]
                    if t!=6: res[r][c]=t; changed=True; continue
                    for r2 in twins_rows(r,res):
                        if res[r2][c]!=6:
                            res[r][c]=res[r2][c]; changed=True; break
    return res
